ROOT=Path("rkern/src")
MODEL=ROOT/"l1j/server/server/model"
for name,body in FILES.items():
    Path(name).write_text(body,encoding="utf-8")
for name in ("Ability.java","Resistance.java","AC.java"):
    (MODEL/name).unlink()
mapping={"getAbility":AMAP,"getResistance":RMAP,"getAC":ACMAP}
# Preserve comments/string literals when rewriting Java.
lex=re.compile(r'"""[\s\S]*?"""|"(?:\\.|[^"\\])*"|\'(?:\\.|[^\'\\])*\'|//[^\n]*|/\*[\s\S]*?\*/')
def mask(s):
    return lex.sub(lambda m: re.sub(r'[^\n]',' ',m.group()),s)
def sub(s,pattern,fn):
    matches=list(re.finditer(pattern,mask(s),re.M))
    for m in reversed(matches):
        s=s[:m.start()]+fn(m)+s[m.end():]
    return s
def rename(s,access,mp):
    return sub(s,r'\b'+access+r'\s*\(\s*\)\s*\.\s*(\w+)\s*\(',lambda m:mp[m[1]]+"(")
changed=0
for p in sorted(ROOT.rglob("*.java")):
    old=p.read_text(encoding="utf-8")
    s=old
    if not re.search(r'\b(?:getAbility|getResistance|getAC|Ability|Resistance|AC|ability|resistance)\b',s):
        continue
    # Simple typed local aliases become direct references to the creature.
    for typ,access,mp in (("Ability","getAbility",AMAP),("Resistance","getResistance",RMAP),("AC","getAC",ACMAP)):
        pat=r'\b'+typ+r'\s+(\w+)\s*=\s*(?:(\w+(?:\.\w+)*)\s*\.\s*)?'+access+r'\s*\(\s*\)\s*;'
        aliases={m[1] for m in re.finditer(pat,mask(s))}
        s=sub(s,pat,lambda m:"var "+m[1]+" = "+(m[2] or "this")+";")
        for alias in aliases:
            s=sub(s,r'\b'+alias+r'\s*\.\s*(\w+)\s*\(',lambda m:alias+"."+mp.get(m[1],m[1])+"(")
        s=sub(s,r'^[ \t]*import\s+l1j\.server\.server\.model\.'+typ+r'\s*;[ \t]*\n',lambda m:"")
    if p.name=="L1CompanionInstance.java":
        start=s.index("public void update_elixir_use_count()")
        end=s.index("public void update_friend_ship_marble()",start)
        part=s[start:end]
        assert part.count("var ability = this;")==1
        s=s[:start]+part.replace("var ability = this;","var ability = L1CompanionInstance.this;")+s[end:]
    if p.name=="L1Magic.java":
        s=sub(s,r'\.ability\s*\.\s*(\w+)\s*\(',lambda m:"."+AMAP[m[1]]+"(")
    if p.name=="L1NpcInstance.java":
        s=sub(s,r'\bresistance\s*\.\s*(\w+)\s*\(',lambda m:RMAP[m[1]]+"(")
    # Rewrite direct calls (including multiline calls).
    for access,mp in mapping.items():
        s=rename(s,access,mp)
    # The resistance lifecycle was explicitly nullable after disposal. Keep that guard.
    s=sub(s,r'\b(\w+(?:\.\w+)*)\s*\.\s*getResistance\s*\(\s*\)\s*(==|!=)\s*null',lambda m:("!" if m[2]=="==" else "")+m[1]+".IsResistanceActive()")
    # Ability and AC were always present on constructed creatures.
    for access in ("getAbility","getAC"):
        s=sub(s,r'\b\w+(?:\.\w+)*\s*\.\s*'+access+r'\s*\(\s*\)\s*(==|!=)\s*null',lambda m:"false" if m[1]=="==" else "true")
    # Simplify only the newly constant guards.
    if s!=old:
        for pattern,repl in [(r'\s*\|\|\s*false\b',''),(r'\bfalse\s*\|\|\s*',''),(r'\s*&&\s*true\b',''),(r'\btrue\s*&&\s*','')]:
            s=sub(s,pattern,lambda m:repl)
        s=sub(s,r'\bfalse\s*\?\s*-?\d+\s*:\s*(\w+(?:\.\w+)*\s*\([^()]*\))',lambda m:m[1])
        s=sub(s,r'\btrue\s*\?\s*(\w+(?:\.\w+)*\s*\([^()]*\))\s*:\s*-?\d+',lambda m:m[1])
        # A constant if with a block and no else can be reduced to the block.
        for m in reversed(list(re.finditer(r'\bif\s*\(\s*true\s*\)\s*\{',mask(s)))):
            k=m.end(); depth=1; masked=mask(s)
            while depth:
                depth+=(masked[k]=='{')-(masked[k]=='}');k+=1
            if not re.match(r'\s*else\b',masked[k:]):
                s=s[:m.start()]+s[m.end()-1:]
        s=sub(s,r'\bif\s*\(\s*true\s*\)\s*(?=\w+\.)',lambda m:"")
    # Reject any unresolved former facade access, except L1StatReset's independent int getter.
    rem=re.search(r'\b(?:getAbility|getResistance)\b|\b(?:Ability|Resistance)\s+\w+\s*[=;,)]|\bnew\s+(?:Ability|Resistance|AC)\s*\(',mask(s))
    if rem: raise RuntimeError(f"unconverted reference {p}: {s[max(0,rem.start()-40):rem.end()+70]}")
    if p.name!="L1StatReset.java":
        rem=re.search(r'\bgetAC\s*\(',mask(s))
        if rem: raise RuntimeError(f"unconverted AC {p}: {s[max(0,rem.start()-40):rem.end()+70]}")
    if s!=old:
        p.write_text(s,encoding="utf-8");changed+=1
print("Migrated Java call-site files:",changed,flush=True)
